let state;try{state=JSON.parse(localStorage.getItem('joy-prototype-v1'))||structuredClone(seed)}catch{state=structuredClone(seed)}
let filters={q:'',brand:'All brands',type:'All types',status:'All',sort:'recommended'},sliderPaused=false,slide=0,profileTab='Activity',menuOpen=false,entryDraft={},toastTimer,returnFocus;
state.entries=(state.entries||[]).filter(e=>offers.some(p=>p.id===e.id));
const logoOf=p=>p.logo||`assets/brand-${p.brand.toLowerCase()}.webp`,brandLogo=p=>brands.includes(p.brand)?`assets/brand-${p.brand.toLowerCase()}.webp`:'',decoOf=p=>`assets/live/deco-${p.brand==='Doritos'?'doritos':p.brand==='Pepsi'?'pepsi':'default'}.png`;
const persist=()=>{try{localStorage.setItem('joy-prototype-v1',JSON.stringify(state))}catch{}};
const date=s=>new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const theme=b=>brands.includes(b)?b:'JOY';
const entry=p=>state.entries.find(e=>e.id===p.id);
const inCountry=p=>p.countries.includes(state.country);
const status=p=>p.status==='Ended'?'Ended':state.signed&&entry(p)?'Entered':p.status;
const badge=(s)=>`<span class="badge ${s==='Ended'?'ended':s==='Entered'?'entered':s==='Ending soon'?'soon':''}">${s==='Entered'?icon('check'):s==='Ending soon'?icon('clock'):''}${s}</span>`;
const route=()=>location.hash.slice(1)||'/';
const go=p=>{if(route()===p)render();else location.hash=p};
const button=(label,path,cls='')=>`<a class="btn ${cls}" href="#${path}">${label}${icon('arrow')}</a>`;
const toast=msg=>{clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)};
function art(p,save=true){if(!p.teaser)return `<div class="card-art obj" data-theme="${theme(p.brand)}"><span class="po-fit">${prizeVisual(p,p.prize,p.ticket)}</span></div>`;if(p.teaser)return `<div class="card-art photo${p.teaserCut?' cut':''}" data-theme="${theme(p.brand)}"><img class="teaser" src="${p.teaser}" alt="" loading="lazy"></div>`;const t=p.ticket||[p.art==='music'?'LIVE MUSIC':p.art==='trip'?'CITY BREAK':'DIGITAL GIFT',p.art==='music'?'YOU + 1':p.art==='trip'?'WEEKEND':p.id==='snack-night'?'£5':'£10',p.art==='music'?'Two tickets. One great night.':p.art==='trip'?'Two people. A new adventure.':'A little something for you.'];return `<div class="card-art ${p.art}" data-theme="${theme(p.brand)}"><span class="brand-tag"><img src="assets/brand-${p.brand.toLowerCase()}.webp" alt="${p.brand}"></span>${save?`<button class="icon-btn save" data-save="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.prize)}" aria-pressed="${state.saved.includes(p.id)}">${icon('heart')}</button>`:''}${p.art==='console'?`<span class="disc"></span><img class="product" src="assets/console.png" alt="PlayStation 5 console and controller">`:`<div class="ticket ${p.art==='voucher'?'second':''}" aria-hidden="true"><div class="ticket-top">${t[0]}</div><strong>${t[1]}</strong><div class="ticket-bottom">${t[2]}</div></div>`}</div>`}
const flagSvg={'United Kingdom':'<svg viewBox="15 0 30 30" aria-hidden="true"><path fill="#012169" d="M0 0h60v30H0z"/><path stroke="#fff" stroke-width="6" d="M0 0l60 30M60 0 0 30"/><path stroke="#c8102e" stroke-width="2" d="M0 0l60 30M60 0 0 30"/><path stroke="#fff" stroke-width="10" d="M30 0v30M0 15h60"/><path stroke="#c8102e" stroke-width="6" d="M30 0v30M0 15h60"/></svg>',Ireland:'<svg viewBox="0 0 3 2" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><path fill="#169b62" d="M0 0h1v2H0z"/><path fill="#fff" d="M1 0h1v2H1z"/><path fill="#ff883e" d="M2 0h1v2H2z"/></svg>',France:'<svg viewBox="0 0 3 2" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><path fill="#0055a4" d="M0 0h1v2H0z"/><path fill="#fff" d="M1 0h1v2H1z"/><path fill="#ef4135" d="M2 0h1v2H2z"/></svg>',Germany:'<svg viewBox="0 0 5 3" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><path d="M0 0h5v1H0z"/><path fill="#dd0000" d="M0 1h5v1H0z"/><path fill="#ffce00" d="M0 2h5v1H0z"/></svg>',Spain:'<svg viewBox="0 0 3 2" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><path fill="#aa151b" d="M0 0h3v2H0z"/><path fill="#f1bf00" d="M0 .5h3v1H0z"/></svg>'};
const brandPhoto={Doritos:'assets/live/brandhero-doritos.webp',Pepsi:'assets/live/brandhero-pepsi.webp','7UP':'assets/live/brandhero-7up.webp'};
const cardMedia=p=>p.teaser?`<img class="wf-card-img${p.teaserCut?' cut':''}" src="${p.teaser}" alt="" loading="lazy">`:brandPhoto[p.brand]?`<img class="wf-card-img brand-photo" data-brand="${p.brand}" src="${brandPhoto[p.brand]}" alt="" loading="lazy">`:`<div class="wf-card-artbox">${art(p,false)}</div>`;
function card(p){const s=status(p),ended=s==='Ended',entered=s==='Entered',saved=state.saved.includes(p.id);return `<article class="wf-card${ended?' is-expired':''}" data-theme="JOY"><div class="wf-card-media" aria-hidden="true">${cardMedia(p)}</div><ul class="wf-card-flags" aria-label="Participating countries">${p.countries.map(c=>`<li><span class="wf-flag" role="img" aria-label="${c}" title="${c}">${flagSvg[c]||''}</span></li>`).join('')}</ul><div class="wf-card-body"><span class="wf-card-logo${p.logoLight?' on-blue':''}"><img src="${logoOf(p)}" alt="${p.brand}"></span><h3>${ended?p.prize:`<a href="#/promotion/${p.id}">${p.prize}</a>`}</h3><ul class="wf-card-meta"><li>${icon('clock')}${p.type} · ${ended?'Ended':s==='Ending soon'?'Ending soon':'Ends'} ${date(p.end).replace(' 2026','')}</li><li${entered?' class="is-entered"':''}>${entered?`${icon('check')}You’ve entered`:`${icon('ticket')}${p.short}`}</li></ul><div class="wf-card-foot">${ended?`<span class="wf-pill blue is-disabled" aria-disabled="true">See promo</span>`:`<a class="wf-pill blue" href="#/promotion/${p.id}" aria-label="See promo: ${esc(p.prize)}">See promo</a>`}<button class="wf-save" data-save="${p.id}" aria-label="${saved?'Unsave':'Save'} ${esc(p.prize)}" aria-pressed="${saved}">${icon('heart')}</button></div></div></article>`}

function cards(list,action){return list.length?`<div class="wf-grid">${list.map(p=>card(p,action)).join('')}</div>`:empty('No promotions here yet','Try another brand or check back for new example promotions.','Browse promotions','/promotions')}
function empty(title,copy,label,path){return `<div class="empty">${icon('search')}<h3>${title}</h3><p>${copy}</p>${label?button(label,path,'secondary'):''}</div>`}
function brandTile(b){return `<div class="brand-tile" data-theme="${theme(b)}"><a href="#/brand/${b}"><img class="brand-logo" src="assets/brand-${b.toLowerCase()}.webp" alt="${b}"></a><button class="icon-btn" data-favourite="${b}" aria-label="${state.favourites.includes(b)?'Unfollow':'Follow'} ${b}" aria-pressed="${state.favourites.includes(b)}">${icon('heart')}</button></div>`}
function entryRows(){return state.entries.length?`<div class="entry-list">${state.entries.map(e=>{const p=offers.find(p=>p.id===e.id);return `<div class="entry-row"><div class="entry-thumb">${p.art==='console'?'<img src="assets/console.png" alt="">':icon('ticket')}</div><div class="entry-main"><h3>${p.prize}</h3><p>${p.brand} · ${p.type} · Entered ${date(e.date)}</p></div><span class="badge entered">${e.outcome==='draw'?'Awaiting draw':e.outcome==='win'?'Example win':'No prize this time'}</span><a class="text-btn" href="#/result/${e.id}">View ${e.outcome==='draw'?'entry':'result'} ${icon('arrow')}</a></div>`}).join('')}</div>`:empty('Your first entry starts here','Once you try a promotion, its confirmation and result will be saved here.','Explore promotions','/promotions')}
function header(){const r=route();return `<div class="prototype-bar">Design prototype · All offers and results are illustrative.<span class="desktop-only"> Example date: 16 Oct 2026.</span><a href="#/about">About this prototype</a></div><header class="header ${menuOpen?'menu-open':''}"><div class="container header-inner"><a href="#/" aria-label="JOY home"><img class="logo" src="assets/joy-white.png" alt="JOY by PepsiCo"></a><nav class="nav" aria-label="Main navigation">${[['/','Home'],['/promotions','Promos']].map(([p,t])=>`<a href="#${p}" ${r===p||(p==='/brands'&&r.startsWith('/brand/'))||(p==='/promotions'&&r.startsWith('/promotion/'))?'aria-current="page"':''}>${t}</a>`).join('')}<details class="brand-menu"><summary ${r.startsWith('/brand')?'aria-current="page"':''}>Brands</summary><div class="brand-menu-panel">${brands.map(b=>`<a href="#/brand/${b}"><img src="assets/brand-${b.toLowerCase()}.webp" alt="${b}"></a>`).join('')}<a class="all-brands" href="#/brands">View all brands ${icon('arrow')}</a></div></details></nav><div class="header-tools">${state.signed?`<a class="profile-link" href="#/profile" aria-label="My JOY account"><span class="avatar">${esc(state.name[0]||'A')}</span><span class="name">My JOY</span></a>`:`<a class="header-login" href="#/join">Log in</a><a class="header-register" href="#/join">Register</a>`}<button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="${menuOpen}">${icon(menuOpen?'close':'menu')}</button></div></div></header>`}
function footer(){return `<section class="wf-news" aria-labelledby="news-title"><div class="wf-wrap wf-news-inner"><div><h2 id="news-title">Stay up to date with your favourite brands</h2><p>Always receive the latest news about current promotions.</p></div><form id="newsletter-form" class="wf-news-form" novalidate><div class="ds-field"><label for="news-email">E-mail</label><input id="news-email" type="email" placeholder="mail@mail.com" autocomplete="email" aria-describedby="news-error"><span id="news-error" class="ds-helper" aria-live="polite">We only use this to send promotion news.</span></div><button class="wf-pill blue" type="submit">Subscribe</button></form></div></section><footer class="wf-footer"><div class="wf-wrap wf-footer-inner"><a href="#/" aria-label="JOY home"><img class="wf-footer-logo" src="assets/joy-footer-live.webp" alt="JOY by PepsiCo"></a><div><nav class="wf-footer-links" aria-label="Footer"><a href="#/help">FAQ</a><a href="#/terms">Terms and Conditions</a><a href="#/privacy">Privacy policy</a><a href="#/help">Contact</a><button type="button" data-action="change-country">Change Country</button></nav><p class="wf-copy">©2025 PepsiCo, Inc · Independent design prototype. All promotions and results are illustrative.</p><p class="wf-demo"><button type="button" data-action="toggle-auth">${state.signed?'View logged-out example':'View logged-in example'}</button><a href="#/about">Design rationale</a></p></div></div></footer>`}
function hero(guest=false){return `<section class="joy-campaign" aria-label="Welcome to JOY"><div class="campaign-copy"><img class="campaign-logo" src="assets/joy-white.png" alt="JOY by PepsiCo">${!guest?`<p class="member-welcome">Hi ${esc(state.name)}, welcome back.</p>`:''}<h1>Your favourite brands. <br>More moments of JOY.</h1><p>Discover rewards from the snacks and drinks you love. Find your next promotion, see how to enter, and follow every result.</p><div class="row">${button('Explore promotions','/promotions','campaign-button')}${guest?'<a class="campaign-secondary" href="#/join">Join JOY</a>':'<a class="campaign-secondary" href="#/profile">My activity</a>'}</div><span class="small campaign-note">Illustrative promotions · Browse before you join</span></div><picture class="campaign-image"><source media="(max-width:700px)" srcset="assets/joy-campaign-mobile.webp"><img src="assets/joy-campaign-desktop.webp" alt="JOY campaign artwork with Pepsi, Walkers and a smiling person in yellow"></picture></section>`}

const MILESTONE=4;
function meter(){const n=state.entries.length,k=n%MILESTONE,done=n>0&&k===0,filled=done?MILESTONE-1:k,away=done?MILESTONE:MILESTONE-k,step=100/(MILESTONE-1);return `<div class="jm" role="img" aria-label="${filled} of ${MILESTONE} entries toward your next example reward"><div class="jm-rail"><span class="jm-track"><span class="jm-fill" style="width:${filled?(filled-1)*step:0}%"></span></span>${Array.from({length:MILESTONE-1},(_,i)=>`<span class="jm-stop ${i<filled?'done':i===filled?'next':''}" style="left:${i*step}%"><span class="jm-dot">${i<filled?icon('check'):i+1}</span><span class="jm-label">Entry ${i+1}</span></span>`).join('')}<span class="jm-stop jm-prize ${filled===MILESTONE-1?'ready':''}" style="left:100%"><svg class="jm-gift" viewBox="0 0 64 64" aria-hidden="true"><path class="jm-bow" d="M32 21C24 6 9 9 13 17c3 5 12 5 19 4Zm0 0c8-15 23-12 19-4-3 5-12 5-19 4Z"/><rect class="jm-lid" x="5" y="20" width="54" height="13" rx="4"/><rect class="jm-box" x="9" y="32" width="46" height="27" rx="4"/><rect class="jm-ribbon" x="27.5" y="20" width="9" height="39"/></svg><i class="jm-spark s1"></i><i class="jm-spark s2"></i><i class="jm-spark s3"></i><span class="jm-label">Reward</span></span></div></div><p class="wf-meter-copy">You are <strong>${away} ${away===1?'entry':'entries'}</strong> away from your next reward!</p>`}
function home(){const active=offers.filter(p=>p.status!=='Ended'&&inCountry(p)).sort((a,b)=>Number(state.favourites.includes(b.brand))-Number(state.favourites.includes(a.brand)));if(!state.signed)return `<section class="wf-register"><div class="wf-wrap"><h1>Register to participate</h1><p>One free JOY account for promotions from Pepsi, Doritos, Rockstar and 7UP — with every entry and result kept in one place.</p><div class="wf-row"><a class="wf-btn yellow" href="#/join">Register</a><a class="wf-btn ghost" href="#/join">Log in</a></div></div></section><section class="wf-section wf-wrap" aria-labelledby="howto-title"><h2 id="howto-title" class="wf-h2 center">How to play</h2><ol class="ds-steps">${[['Snack','Pick up a participating pack or can.',`<img src="assets/joy-products.webp" alt="PepsiCo snacks and drinks">`],['Play','Enter your pack code, or confirm a free entry.',`<div class="wf-code" aria-hidden="true"><span>Your code</span><strong>JOY2026</strong></div>`],['Win','See an instant result or your draw date.',`<img src="assets/console.png" alt="Example prize: a games console">`]].map(([t,c,img],i)=>`<li class="ds-card-step"><span class="ds-step-circle" aria-hidden="true"></span><span class="ds-num" aria-hidden="true">${i+1}</span><h3 class="ds-step-text"><span class="ds-step-kicker">${t}</span>${c}</h3><div class="ds-card-img">${img}</div></li>`).join('')}</ol></section><section class="wf-section wf-wrap"><div class="wf-head"><h2 class="wf-h2">Suggested promotions</h2><a class="wf-link" href="#/promotions">View all ${icon('arrow')}</a></div>${cards(active.slice(0,4),'enter')}</section>`;const suggested=active.filter(p=>!entry(p)).slice(0,4),entered=state.entries.map(e=>offers.find(p=>p.id===e.id)).filter(Boolean);return `<section class="wf-greet"><div class="wf-wrap"><h1>Hi ${esc(state.name)},</h1>${meter()}<p class="wf-meter-note">Example milestone: every ${MILESTONE} entries unlocks a bonus reward. <a href="#/profile">See my activity</a></p></div></section><section class="wf-section wf-wrap"><div class="wf-head"><h2 class="wf-h2">Suggested promotions</h2><a class="wf-link" href="#/promotions">View all ${icon('arrow')}</a></div>${cards(suggested,'enter')}</section><section class="wf-section wf-wrap"><div class="wf-head"><h2 class="wf-h2">Entered promotions</h2><a class="wf-link" href="#/profile">All activity ${icon('arrow')}</a></div>${entered.length?cards(entered):empty('Your first entry starts here','Once you enter a promotion, it appears here with its status.','Explore promotions','/promotions')}</section>`}
function steps(t,copy){return `<div class="steps">${t.map((x,i)=>`<div class="step"><span class="step-number">${i+1}</span><div><h3>${x}</h3><p>${copy[i]}</p></div></div>`).join('')}</div>`}
function filtered(){let list=offers.filter(p=>inCountry(p)&&(filters.brand==='All brands'||p.brand===filters.brand)&&(filters.type==='All types'||p.type===filters.type)&&(!filters.q||`${p.brand} ${p.title} ${p.prize} ${p.type}`.toLowerCase().includes(filters.q.toLowerCase()))&&(filters.status==='All'?true:filters.status==='Available'?p.status!=='Ended':filters.status==='Entered'?state.signed&&!!entry(p):filters.status==='Saved'?state.saved.includes(p.id):p.status==='Ended'));if(filters.sort==='ending')list.sort((a,b)=>a.end.localeCompare(b.end));else if(filters.sort==='brand')list.sort((a,b)=>a.brand.localeCompare(b.brand));else list.sort((a,b)=>Number(state.favourites.includes(b.brand))-Number(state.favourites.includes(a.brand)));return list.sort((a,b)=>Number(a.status==='Ended')-Number(b.status==='Ended'))}
const opts=(a,v)=>a.map(t=>`<option ${t===v?'selected':''}>${t}</option>`).join('');
const range=p=>`${date(p.start)} – ${date(p.end)}`;
const featured=()=>offers.filter(p=>p.status!=='Ended'&&inCountry(p)).slice(0,3);
function heroSlide(p,i,n,clone){const deco=decoOf(p);return `<div class="wf-slide${clone?' clone':''}" data-theme="JOY" data-brand="${p.brand}" ${clone?'aria-hidden="true" inert':`role="group" aria-roledescription="slide" aria-label="${i+1} of ${n}: ${esc(p.heroTitle||p.title)}" ${i===slide?'':'aria-hidden="true" inert'}`}><img class="wf-slide-deco one" src="${deco}" alt=""><img class="wf-slide-deco two" src="${deco}" alt=""><div class="wf-slide-copy">${p.logo?`<img class="wf-slide-logo" src="${p.logo}" alt="">`:''}<p class="wf-dates">${icon('calendar')}${range(p)}</p><h2>${p.heroTitle||p.title}</h2><a class="wf-btn yellow sm" href="#/promotion/${p.id}" draggable="false" ${clone?'tabindex="-1"':''}>See more</a><p class="wf-caps">${p.heroCaption||`${p.type==='Instant win'?'Instant win':'Chance to win'} · ${p.prize}`}</p></div><div class="wf-slide-art"><div class="wf-slide-circle${p.hero?' photo':''}" data-theme="${theme(p.brand)}">${p.hero?`<picture><source media="(max-width:700px)" srcset="${p.hero[1]}"><img class="wf-slide-photo" src="${p.hero[0]}" alt="${esc(p.title)}: ${esc(p.prize)}"${i===0&&!clone?'':' loading="lazy"'}></picture>`:art(p,false)}</div></div></div>`}
function gallery(){const f=featured(),n=f.length;if(slide>=n)slide=0;return `<section class="wf-carousel" aria-roledescription="carousel" aria-label="Featured promotions"><div class="wf-viewport"><div class="wf-track" style="transform:translateX(-${(slide+1)*100}%)">${heroSlide(f[n-1],n-1,n,true)}${f.map((p,i)=>heroSlide(p,i,n,false)).join('')}${heroSlide(f[0],0,n,true)}</div></div><div class="wf-dots">${f.map((p,i)=>`<button type="button" data-slide="${i}" aria-label="Show featured promotion ${i+1}: ${esc(p.prize)}" aria-current="${i===slide}"></button>`).join('')}</div></section><div class="wf-wrap"><h1 class="wf-h2 wf-page-title">Promotions</h1><div class="wf-filter-bar" role="group" aria-label="Promotion options"><div class="field"><label for="brand-filter">Brand</label><select id="brand-filter">${opts(['All brands',...brands],filters.brand)}</select></div><div class="field"><label for="type-filter">Promotion type</label><select id="type-filter">${opts(['All types','Prize draw','Instant win'],filters.type)}</select></div><div class="field"><label for="availability">Show</label><select id="availability">${opts(['All','Available','Entered','Saved','Expired'],filters.status)}</select></div><div class="field"><label for="sort">Sort by</label><select id="sort"><option value="recommended" ${filters.sort==='recommended'?'selected':''}>Recommended</option><option value="ending" ${filters.sort==='ending'?'selected':''}>Ending soonest</option><option value="brand" ${filters.sort==='brand'?'selected':''}>Brand A–Z</option></select></div></div><p id="result-count" role="status" class="wf-result-count"></p><div id="promotion-grid" class="wf-grid"></div></div>`}
function sizeHero(){const c=$('.wf-carousel');if(c)document.documentElement.style.setProperty('--hero-top',`${c.getBoundingClientRect().top+scrollY}px`)}
function trackTo(pos,animate=true){const t=$('.wf-track');if(!t)return;t.style.transition=animate?'':'none';t.style.transform=`translateX(-${pos*100}%)`}
function setSlide(n){const s=document.querySelectorAll('.wf-slide:not(.clone)');if(!s.length)return;const len=s.length,pos=n<0?0:n>=len?len+1:n+1;slide=(n+len)%len;trackTo(pos,!reducedMotion());if(pos!==slide+1){const t=$('.wf-track');let timer;const snap=()=>{clearTimeout(timer);t.removeEventListener('transitionend',onEnd);trackTo(slide+1,false)},onEnd=e=>{if(e.target===t)snap()};t.addEventListener('transitionend',onEnd);timer=setTimeout(snap,reducedMotion()?0:650)}s.forEach((el,i)=>{const on=i===slide;el.toggleAttribute('inert',!on);on?el.removeAttribute('aria-hidden'):el.setAttribute('aria-hidden','true')});document.querySelectorAll('[data-slide]').forEach((d,i)=>d.setAttribute('aria-current',String(i===slide)))}
const reducedMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
setInterval(()=>{const c=$('.wf-carousel');if(c&&!drag&&!reducedMotion()&&!c.matches(':hover,:focus-within')&&!document.hidden)setSlide(slide+1)},4000);
function updateResults(){if(!$('#promotion-grid'))return;const list=filtered(),live=list.filter(p=>p.status!=='Ended').length;$('#result-count').textContent=`${list.length} ${list.length===1?'promotion':'promotions'} in ${state.country} · ${live} open${list.length-live?` · ${list.length-live} expired`:''}`;$('#promotion-grid').innerHTML=list.length?list.map(p=>card(p)).join(''):empty(filters.status==='Entered'&&!state.signed?'Log in to see your entries':'Nothing matches just yet','Try another brand or promotion type, or choose a different example market.','',null)+`<div class="wf-row"><button class="wf-pill" data-action="clear-filters">Show all promotions</button>${!state.signed&&filters.status==='Entered'?'<a class="wf-pill yellow" href="#/join">Log in</a>':''}</div>`}
const planeSvg='<svg class="po-plane" viewBox="0 0 24 24" aria-hidden="true"><path d="M21 16v-2l-8-5V3.5a1.5 1.5 0 0 0-3 0V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5z"/></svg>';
function prizeObj(kind,p,o={}){const b=p?p.brand:'JOY',logo=p?logoOf(p):'';switch(kind){
case 'console':return '<img class="po-img" src="assets/console.png" alt="">';
case 'giftcard':return `<div class="po po-giftcard" data-brand="${b}"><span class="po-gc-logo"><img src="${logo}" alt=""></span><span class="po-chip"></span><strong class="po-amount">${o.amount||''}</strong><span class="po-gc-label">${o.label||'Gift card'}</span><span class="po-gc-num">•••• 2026</span></div>`;
case 'cash':return `<div class="po po-cash"><span class="po-cash-corner">£</span><span class="po-cash-seal"></span><strong class="po-amount">${o.amount||''}</strong><span class="po-cash-label">Cash prize</span><span class="po-cash-corner br">£</span></div>`;
case 'ticket':return `<div class="po po-ticket" data-brand="${b}"><div class="po-tk-main"><span class="po-tk-top">${o.top||'LIVE MUSIC'}</span><strong>${o.big||'YOU + 1'}</strong><span class="po-tk-sub">${o.sub||'Two tickets'}</span></div><div class="po-tk-stub"><span>ADMIT</span><strong>2</strong></div></div>`;
case 'pass':return `<div class="po po-pass" data-brand="${b}"><span class="po-lanyard"></span><span class="po-clip"></span><div class="po-pass-card"><span class="po-hole"></span><span class="po-pass-band">${o.top||'FESTIVAL'}</span><strong>${o.big||'WEEKEND'}</strong><span class="po-pass-sub">${o.sub||'All access · 2 people'}</span><span class="po-barcode"></span></div></div>`;
case 'boarding':return `<div class="po po-boarding" data-brand="${b}"><div class="po-bp-head">${planeSvg}<span>Boarding pass</span></div><div class="po-bp-route"><strong>LON</strong><span class="po-bp-line">${planeSvg}</span><strong>${o.to||'SUN'}</strong></div><div class="po-bp-meta"><span>Seats<b>2</b></span><span>Class<b>Economy</b></span><span>Gate<b>J7</b></span></div></div>`;
case 'headset':return `<svg class="po-svg po-headset" data-brand="${b}" viewBox="0 0 120 120" aria-hidden="true"><path d="M22 72V60a38 38 0 0 1 76 0v12" fill="none" stroke="#1d1d1f" stroke-width="9" stroke-linecap="round"/><rect x="10" y="62" width="26" height="40" rx="12" fill="#1d1d1f"/><rect x="84" y="62" width="26" height="40" rx="12" fill="#1d1d1f"/><rect x="15" y="69" width="11" height="26" rx="5.5" class="po-accent"/><rect x="94" y="69" width="11" height="26" rx="5.5" class="po-accent"/><path d="M22 100c2 9 12 13 26 13" fill="none" stroke="#1d1d1f" stroke-width="4" stroke-linecap="round"/><circle cx="51" cy="113" r="5" fill="#1d1d1f"/></svg>`;
case 'merch':return `<div class="po po-merch" data-brand="${b}"><svg class="po-svg" viewBox="0 0 120 120" aria-hidden="true"><path class="po-tee" d="M42 14 17 27l9 24 13-6v61h42V45l13 6 9-24-25-13c-3 8-11 13-18 13s-15-5-18-13z"/></svg><span class="po-merch-logo"><img src="${logo}" alt=""></span></div>`;
case 'bundle':return ['Doritos','Walkers'].includes(b)?'<img class="po-img po-packs" src="assets/joy-products.webp" alt="">':`<div class="po po-cans" data-brand="${b}"><span class="po-can"></span><span class="po-can mid"><img src="${logo}" alt=""></span><span class="po-can"></span></div>`;
default:return `<svg class="po-svg po-giftbox" data-brand="${b}" viewBox="0 0 120 120" aria-hidden="true"><rect x="18" y="52" width="84" height="56" rx="6" class="po-box"/><rect x="12" y="38" width="96" height="20" rx="5" class="po-lid"/><rect x="54" y="38" width="12" height="70" class="po-ribbon"/><path d="M60 38c-6-14-26-18-26-6 0 8 14 8 26 6zM60 38c6-14 26-18 26-6 0 8-14 8-26 6z" class="po-ribbon"/></svg>`}}
function prizeVisual(p,name,a){const n=String(name).toLowerCase(),t=Array.isArray(a)?a:[],amt=(String(name).match(/£\d+/)||[t[1]||''])[0];
if(a==='console'||/console|ps5/.test(n))return prizeObj('console',p);
if(/headset/.test(n))return prizeObj('headset',p);
if(/holiday|trip|city break/.test(n))return prizeObj('boarding',p,{to:/vegas/.test(n)?'LAS':/city/.test(n)?'BCN':'SUN'});
if(/festival|weekend.*pass|music passes/.test(n))return prizeObj('pass',p,{top:'FESTIVAL',big:'WEEKEND',sub:'All access · 2 people'});
if(/ticket/.test(n))return prizeObj('ticket',p,/match|football/.test(n)?{top:'MATCH DAY',big:'YOU + 1',sub:'Two seats · One big game'}:{top:'LIVE MUSIC',big:'YOU + 1',sub:'Two tickets · One great night'});
if(/gift card|voucher|credit/.test(n))return prizeObj('giftcard',p,{amount:amt,label:/stream/.test(n)?'Streaming gift card':/travel/.test(n)?'Travel gift card':/snack/.test(n)?'Snack voucher':'Digital gift card'});
if(/^\s*£\d+\s*$/.test(name)||/cash/.test(n))return prizeObj('cash',p,{amount:amt});
if(/merch|vanity|kit/.test(n))return prizeObj('merch',p);
if(/bundle|multipack|cans|pack|cooler/.test(n))return prizeObj('bundle',p);
return prizeObj('giftbox',p)}
function stepMock(p,i){if(i===0)return `<div class="mock"><span class="mock-title">Can I take part?</span>${['Age 18 or over',p.countries.length>1?'Live in a listed country':`Live in the ${p.countries[0]}`,p.code?'Have a promo pack':'No purchase needed'].map(t=>`<span class="mock-row"><i class="mock-box">${icon('check')}</i>${t}</span>`).join('')}</div>`;if(i===1)return p.code?`<div class="mock"><span class="mock-title">Pack code</span><span class="mock-input">JOY2026<i class="mock-caret"></i></span><span class="mock-btn">Submit code</span></div>`:`<div class="mock"><span class="mock-title">Confirm your entry</span><span class="mock-row"><i class="mock-box">${icon('check')}</i>I’m 18+ and agree to the rules</span><span class="mock-btn">Enter now</span></div>`;return p.type==='Instant win'?`<div class="mock mock-result"><span class="mock-badge">${icon('gift')}</span><strong>You’ve won!</strong><span>${esc(p.prize)}</span></div>`:`<div class="mock mock-result"><span class="mock-badge">${icon('check')}</span><strong>You’re in the draw</strong><span>Winners drawn after ${date(p.end)}</span></div>`}
function detailBanner(p){const ph=brandPhoto[p.brand];return p.header?`<section class="wf-detail-banner"><picture><source media="(max-width:700px)" srcset="${p.header[1]}"><img src="${p.header[0]}" alt="${esc(p.title)}: ${esc(p.prize)}"></picture></section>`:ph?`<section class="wf-detail-banner brand"><img src="${ph}" alt=""></section>`:`<section class="wf-detail-hero"><div class="wf-detail-art">${art(p,false)}</div></section>`}
function details(p){const e=entry(p),eligible=inCountry(p),closed=p.status==='Ended',s=status(p);const cta=closed?'<span class="wf-pill disabled" aria-disabled="true">Entry closed</span>':!eligible?`<span class="wf-pill disabled" aria-disabled="true">Not available in ${state.country}</span>`:state.signed&&e?`<a class="wf-pill yellow" href="#/result/${p.id}">View your entry</a>`:`<a class="wf-pill yellow" href="#${state.signed?'/enter/'+p.id:'/join?next='+p.id}">${state.signed?'Participate now':'Log in to participate'}</a>`;const stepData=[['Check you can take part',`Age 18+ and living in ${p.countries.join(', ')}. ${p.short}.`,'pin'],[p.code?'Enter your code':'Confirm your entry',p.code?'Find the code on your pack. For this prototype, use JOY2026 — no purchase needed.':'No purchase needed. Confirm the entry in one simple step.','ticket'],[p.type==='Instant win'?'See your result':'You’re in the draw',p.type==='Instant win'?'Your result appears straight away and is saved in My JOY.':`Your confirmation is saved in My JOY. Winners are drawn after ${date(p.end)}.`,p.type==='Instant win'?'gift':'check']];const faqs=[['Is a prize guaranteed?',`No. ${p.type==='Prize draw'?'This is a chance-based draw; odds depend on the number of valid entries and prizes available.':'An instant-win entry can receive a win or a no-prize result.'} Prototype outcomes are chosen for testing and don’t represent real odds.`],['How many times can I enter?','One entry per person for this example promotion. Your entry and its status are always visible in My JOY.'],['What happens after I enter?',p.type==='Instant win'?'You see a result immediately and can return to it from My JOY.':`Your entry is saved as awaiting draw. This example shows a result date of ${date(p.end)}. No real emails are sent.`],['Will I need to sign in again?','No. You stay in one JOY journey from browsing to result. If a real offer used an external provider, JOY would say so before you leave.']];return `<div class="wf-detail" data-theme="${theme(p.brand)}">${detailBanner(p)}<div class="wf-detail-band" data-theme="JOY" data-brand="${p.brand}"><img class="wf-band-deco one" src="${decoOf(p)}" alt=""><img class="wf-band-deco two" src="${decoOf(p)}" alt=""><p class="wf-dates">${icon('calendar')}${range(p)}</p><h1>${p.title}</h1><p class="wf-detail-sub">${p.prize}</p>${closed?'<span class="wf-btn yellow sm disabled" aria-disabled="true">Entry closed</span>':!eligible?`<span class="wf-btn yellow sm disabled" aria-disabled="true">Not available in ${state.country}</span>`:state.signed&&e?`<a class="wf-btn yellow sm" href="#/result/${p.id}">View your entry</a>`:`<a class="wf-btn yellow sm" href="#${state.signed?'/enter/'+p.id:'/join?next='+p.id}">Participate here</a>`}</div><nav class="wf-subnav" aria-label="Promotion sections"><div class="wf-subnav-inner">${[['prizes','Prizes'],['steps','Steps'],['faq','FAQs'],['rules','Terms and conditions']].map(([id,t])=>`<a href="#/promotion/${p.id}" data-scroll="${id}">${t}</a>`).join('')}${cta}</div></nav><section id="prizes" class="wf-band wf-prizes"><h2 class="wf-caps-h">Prizes</h2><div class="wf-prize-wrap">${p.prizes.length>3?`<button type="button" class="wf-arrow" data-action="prize-prev" aria-label="Previous prizes">${icon('back')}</button>`:''}<ul class="wf-prize-track" id="prize-track">${p.prizes.map(([qty,name,a,img],i)=>`<li class="ds-card-prize${img?' has-photo':''}"><span class="ds-num">${i+1}</span>${img?`<img class="ds-prize-photo" src="assets/live/${img}.webp" alt="" loading="lazy">`:`<span class="ds-card-img"><span class="po-fit">${prizeVisual(p,name,a)}</span></span>`}<strong>${name}</strong>${qty?`<span class="ds-card-qty">${qty}</span>`:''}</li>`).join('')}</ul>${p.prizes.length>3?`<button type="button" class="wf-arrow" data-action="prize-next" aria-label="Next prizes">${icon('arrow')}</button>`:''}</div><p class="wf-prize-note">${closed?'This promotion has ended. These prizes are kept for reference.':p.type==='Instant win'?'Instant win: you’ll see a win or no-prize result straight after entering.':'Prize draw: entering gives you a chance to win. You’ll get an entry confirmation, not an instant prize.'}</p></section><section id="steps" class="wf-band wf-steps"><h2 class="wf-caps-h">Steps</h2><ol class="ds-steps">${stepData.map(([t,c,ic],i)=>`<li class="ds-card-step has-desc"><span class="ds-step-circle" aria-hidden="true"></span><span class="ds-num" aria-hidden="true">${i+1}</span><h3 class="ds-step-text">${t}</h3><div class="ds-card-img" aria-hidden="true">${stepMock(p,i)}</div><p class="ds-step-desc">${c}</p></li>`).join('')}</ol><p class="wf-steps-note">${p.description}</p><div class="wf-center">${cta}</div></section><section id="faq" class="wf-band wf-faq"><h2 class="wf-caps-h">Frequently asked questions</h2><div class="wf-faq-list">${faqs.map(([q,a])=>`<details><summary>${q}${icon('chevronDown')}</summary><p>${a}</p></details>`).join('')}</div></section><section id="rules" class="wf-band wf-terms"><h2 class="wf-caps-h">Terms and conditions</h2><p>Illustrative eligibility: residents aged 18+ in ${p.countries.join(', ')}. One simulated entry per promotion. Opens ${date(p.start)}; entry closes ${date(p.end)} at 23:59 local market time. ${p.requirement}. These are prototype assumptions, not official promotion terms.</p><div class="wf-detail-links"><a href="#/help">Contact (promotion)</a><a href="#/terms">Terms and conditions (promotion)</a></div></section></div>`}
function brandsPage(){return `<div class="intro"><span class="eyebrow">More favourites. One place.</span><h1>Find your kind of JOY.</h1><p>Explore each brand’s promotions. Follow your favourites for more relevant suggestions.</p></div><div class="brand-grid">${brands.map(brandTile).join('')}</div><section class="section"><div class="section-head"><h2>From the brands you follow</h2></div>${cards(offers.filter(p=>p.status!=='Ended'&&inCountry(p)&&state.favourites.includes(p.brand)))}</section>`}
const brandInfo={Pepsi:{welcome:'Maximum taste. Big moments.',site:'https://www.pepsi.com',hero:'assets/live/brandhero-pepsi.webp',news:[['Where there’s a ball there’s a way.','#ThirstyForMore','','assets/live/video-pepsi-ball.mp4'],['Good music. Even better company.','Two tickets, one great night: explore the example live-music draw.','live-music']]},Doritos:{welcome:'Dare yourself! Be a triangle in a world full of circles.',site:'https://www.doritos.com',hero:'assets/live/brandhero-doritos.webp',news:[['See how we set a world record for the longest cheese pull','Go behind the scenes as Doritos pulls off the world’s highest ever cheese pull.','','assets/live/video-doritos-cheesepull.mp4'],['Be a triangle in a world of circles.','Doritos: for the bold in everyone.','','assets/live/video-doritos-triangle.mp4']]},Rockstar:{welcome:'Fuel for every break.',site:'https://www.rockstarenergy.com',news:[['A weekend of live music.','Two passes, three stages, zero sleep. Take a look at the example festival draw.','weekend-pass'],['A little win for your next break.','Find out straight away with the example £10 gift card instant win.','instant-break']]},'7UP':{welcome:'Refreshing 7UP taste, zero sugar. The lemon & lime twist that refreshes like no other.',site:'https://www.pepsico.co.uk',hero:'assets/live/brandhero-7up.webp',news:[['7UP Zero | Taste that lifts you up','The refreshing taste of lemon and lime. Zero sugar.','','assets/live/video-7up.mp4'],['Sunshine, bottled.','Swap grey skies for a week in the sun with the example beach-holiday draw.','sunny-escape']]}};
const deco=b=>`<span class="wf-deco left" aria-hidden="true"><i></i><i></i><i></i></span><span class="wf-deco right" aria-hidden="true"><i></i><i></i><i></i></span>`;
function brandCard(p,other){const ended=p.status==='Ended';return `<article class="wf-wide ${ended?'is-expired':''}" data-theme="JOY"><div class="wf-wide-copy">${p.logo?`<img class="wf-wide-lockup${p.logoDark?' plate':''}" src="${p.logo}" alt="${p.brand}">`:`<span class="wf-wide-plate"><img class="wf-wide-logo" src="assets/brand-${p.brand.toLowerCase()}.webp" alt="${p.brand}"></span>`}<p class="wf-dates">${icon('calendar')}${range(p)}</p><h3>${p.title}</h3><p class="wf-wide-sub">${p.type==='Instant win'?'Instant win':'Chance to win'} · ${p.prize}</p>${ended?'<span class="wf-pill is-disabled" aria-disabled="true">View promo</span>':`<a class="wf-pill yellow" href="#/promotion/${p.id}" ${other?'tabindex="-1"':''}>Go to promo</a>`}</div><div class="wf-wide-art"><div class="wf-wide-circle" data-theme="${theme(p.brand)}">${art(p,false)}</div></div></article>`}
function brandPage(b){const info=brandInfo[b],list=offers.filter(p=>p.brand===b&&inCountry(p)&&p.status!=='Ended'),ended=offers.filter(p=>p.brand===b&&inCountry(p)&&p.status==='Ended'),others=offers.filter(p=>p.brand!==b&&inCountry(p)&&p.status!=='Ended'),following=state.favourites.includes(b),site=`<a class="wf-pill white" href="${info.site}" target="_blank" rel="noopener">Visit brand website${ext}<span class="visually-hidden"> (opens in a new tab)</span></a>`;return `<div class="wf-brand" data-theme="${theme(b)}" data-brand="${b}"><section class="wf-brand-hero"><div class="wf-brand-mast${info.hero?' photo':''}"${info.hero?` style="background-image:url('${info.hero}')"`:''}>${info.hero?'':`<img class="wf-brand-logo" src="assets/brand-${b.toLowerCase()}.webp" alt="${b}">`}</div><div class="wf-brand-band">${deco(b)}<h1>Welcome to ${b} on Joy by PepsiCo!</h1><div class="wf-row">${site}<button type="button" class="wf-pill ghost-white" data-favourite="${b}" aria-pressed="${following}">${icon('heart')}${following?'Following':'Follow brand'}</button></div><p>${info.welcome}</p></div></section><section class="wf-brand-section" aria-labelledby="active-title"><h2 id="active-title" class="wf-h2 center-sm">Active promos</h2>${list.length?`<div class="wf-wide-list">${list.map(p=>brandCard(p)).join('')}</div>`:empty('No active promos right now',`There are no open ${b} promotions in ${state.country}. Follow ${b} to see new ones first.`,'Browse all promos','/promotions')}</section><section class="wf-brand-section" aria-labelledby="news-heading"><h2 id="news-heading" class="wf-h2 center-sm">Latest brand news</h2><div class="wf-news-list">${info.news.map(([t,c,id,video],i)=>{const p=offers.find(x=>x.id===id);return `<article class="wf-news-row ${i%2?'flip':''}" data-theme="${theme(b)}">${video?`<div class="wf-news-media is-video"><video controls playsinline preload="metadata" src="${video}#t=0.5" aria-label="${esc(t)} (video, no captions available)"></video></div>`:`<a class="wf-news-media" href="#/promotion/${p.id}" tabindex="-1" aria-hidden="true">${art(p,false)}</a>`}<div class="wf-news-text"><span class="wf-news-tag">${video?'Brand news':'Example news'}</span><h3>${t}</h3><p>${c}</p><div class="wf-row">${p?`<a class="wf-pill blue" href="#/promotion/${p.id}">Read more</a>`:''}<a class="wf-pill" href="${info.site}" target="_blank" rel="noopener">Discover${ext}<span class="visually-hidden"> ${b} website (opens in a new tab)</span></a></div></div></article>`}).join('')}</div></section><section class="wf-brand-section wf-brand-more" aria-labelledby="more-title">${deco(b)}<h2 id="more-title" class="wf-h2">Want to know more about ${b}?</h2><a class="wf-pill blue" href="${info.site}" target="_blank" rel="noopener">Visit brand website${ext}<span class="visually-hidden"> (opens in a new tab)</span></a></section>${ended.length?`<section class="wf-brand-section" aria-labelledby="expired-title"><h2 id="expired-title" class="wf-h2 center-sm">Expired promos</h2><div class="wf-wide-list">${ended.map(p=>brandCard(p)).join('')}</div></section>`:''}${others.length?`<section class="wf-brand-section" aria-labelledby="others-title"><h2 id="others-title" class="wf-h2 center-sm">Check out other brand promotions</h2><div class="wf-others"><button type="button" class="wf-arrow blue" data-action="others-prev" aria-label="Previous promotion">${icon('back')}</button><div class="wf-others-track" id="others-track" tabindex="0" aria-label="Other brand promotions">${others.map(p=>`<div class="wf-others-slide">${brandCard(p)}</div>`).join('')}</div><button type="button" class="wf-arrow blue" data-action="others-next" aria-label="Next promotion">${icon('arrow')}</button></div><div class="wf-dots wf-others-dots">${others.map((p,i)=>`<button type="button" data-other="${i}" aria-label="Show ${esc(p.brand)}: ${esc(p.prize)}" aria-current="${i===0}"></button>`).join('')}</div></section>`:''}</div>`}
function flowSteps(current,loading=false){const c=k=>k===current?`current${loading?' loading':''}`:loading&&k<current?'done':'';return `<div class="flow-steps" aria-label="Participation progress"><span class="${c(1)}">1 · Requirements</span><span class="${c(2)}">2 · Entry</span><span class="${c(3)}">3 · ${current===3?'Result':'Confirmation'}</span></div>`}
function participationShell(p,body,resultView=false,loading=false){return `<section class="participation" data-theme="${theme(p.brand)}"><aside class="participation-copy"><a href="#/promotion/${p.id}" class="back-link">${icon('back')} Back to promotion</a><img class="participation-brand" src="${logoOf(p)}" alt="${p.brand}"><p class="eyebrow">${p.type} · Example promotion</p><h${resultView?'2':'1'}>${loading?'Your result is on its way.':resultView?'Here is your result.':p.code?'Enter your code. Find your next moment.':'You’re one step away.'}</h${resultView?'2':'1'}><p class="participation-prize">${p.prize}</p><p>${resultView?'Your confirmation and result are saved together in My JOY.':p.requirement+'. Check your entry below, then see what happens next.'}</p>${!resultView?`<div class="participation-summary"><span>${icon('pin')}${state.country} · Age 18+</span><span>${icon('clock')}Ends ${date(p.end)}</span><span>${icon('info')}${p.type==='Instant win'?'A result straight after entry':'Confirmation now. Draw result later.'}</span></div>`:''}</aside><div class="participation-stage"><div class="participation-content">${flowSteps(resultView?3:2,loading)}${body}</div></div></section>`}
function enter(p){if(!state.signed)return join(p.id);if(p.status==='Ended'||!inCountry(p))return details(p);if(entry(p)&&entryDraft.replay!==p.id)return result(p);return participationShell(p,`<form id="entry-form" data-id="${p.id}" class="panel form-stack" novalidate><div><h2>${p.code?'One code. You’re ready to go.':'Your entry, one step away.'}</h2><p style="margin-top:12px">${p.type==='Instant win'?'You’ll see your result on the next screen.':'You’re entering a prize draw. A prize isn’t guaranteed.'}</p></div><div class="notice">Testing only · ${p.code?'Use the example code <strong>JOY2026</strong>. No real purchase or code is required.':'No purchase or personal information required for this example.'}</div>${p.code?`<div class="field"><label for="entry-code">Example ${p.brand==='Rockstar'?'can':'pack'} code (required)</label><details class="code-guide"><summary>Where is my code?</summary><p>On a real promotion, check the participating pack near its best-before date. For this prototype, enter <strong>JOY2026</strong>.</p></details><input id="entry-code" name="code" type="text" autocomplete="off" spellcheck="false" maxlength="20" aria-describedby="code-help code-error" value="${esc(entryDraft.code||'')}" placeholder="e.g. JOY2026"><span id="code-help" class="small muted">7 characters. Spaces and letter case don’t matter.</span><span id="code-error" class="error"></span></div>`:''}<label class="check"><input type="checkbox" id="eligible" ${entryDraft.eligible?'checked':''}><span>I confirm the example eligibility (required).<small>Age 18+ and resident in ${state.country}. This does not verify your real identity.</small></span></label><label class="check"><input type="checkbox" id="rules-agree" ${entryDraft.rules?'checked':''}><span>I understand this is a simulated entry (required).<small><a href="#/promotion/${p.id}" data-action="save-draft">Read example rules</a>. No prize or email will be issued.</small></span></label><div id="form-error" class="error" role="alert"></div><details class="demo-controls"><summary>Try a different prototype outcome</summary><div class="field"><label for="test-outcome">Prototype test scenario</label><select id="test-outcome">${p.type==='Instant win'?'<option value="loss">No prize result</option><option value="win">Winning result</option>':'<option value="draw">Entry confirmation</option>'}<option value="error">Recoverable connection error</option></select><span class="small muted">This tester control selects the demonstration outcome. It is not part of a live promotion.</span></div></details><div class="form-actions"><a class="text-btn" href="#/promotion/${p.id}">Cancel</a><button class="btn" type="submit">${p.type==='Instant win'?'See my result':'Submit example entry'} ${icon('arrow')}</button></div></form>`)}
const fills={Walkers:{kind:'snack'},Rockstar:{kind:'drink',liquid:'#f2c230',deep:'#c98a12',foam:'#fff4c2'},'7UP':{kind:'drink',liquid:'#c9ee26',deep:'#7cc21e',foam:'#f3ffd6'},Pepsi:{kind:'drink',liquid:'#4a2414',deep:'#1e0c05',foam:'#d8b58c'},Doritos:{kind:'snack'},default:{kind:'drink',liquid:'#ffe600',deep:'#f2b800',foam:'#fffbe0'}};
function reveal(p){if(!state.signed)return join(p.id);if(!entry(p)||p.type!=='Instant win')return details(p);const f=fills[p.brand]||fills.default,logo=logoOf(p);const stage=f.kind==='snack'?`<div class="wf-bowl-scene">${[0,1,2,3,4,5,6].map(i=>`<i class="wf-fall" style="--i:${i}"></i>`).join('')}<div class="wf-bowl"><img src="${logo}" alt=""></div></div>`:`<div class="wf-glass-scene" style="--liquid:${f.liquid};--deep:${f.deep};--foam:${f.foam}"><span class="wf-pour"></span><div class="wf-glass"><div class="wf-liquid"><span class="wf-wave"></span>${'<i></i>'.repeat(7)}</div><img class="wf-glass-logo" src="${logo}" alt=""></div></div>`;return participationShell(p,`<div class="wf-reveal in-stage" data-brand="${p.brand}" data-id="${p.id}"><div class="wf-reveal-inner"><p class="wf-reveal-eyebrow">Instant win · ${p.prize}</p><div class="wf-stage" aria-hidden="true">${stage}</div><h1 id="reveal-hint" role="status">${f.kind==='snack'?'Filling the bowl…':'Pouring your result…'}</h1><a class="wf-skip" href="#/result/${p.id}">Skip</a></div></div>`,true,true)}
function startReveal(){const s=$('.wf-reveal');if(!s)return;const r=route(),fast=reducedMotion();setTimeout(()=>{if(route()===r)$('#reveal-hint').textContent='Almost there…'},fast?400:1900);setTimeout(()=>{if(route()===r)go('/result/'+s.dataset.id)},fast?1200:3400)}
function result(p){if(!state.signed)return join(p.id);const e=entry(p);if(!e)return empty('No entry yet','Take a look at the promotion requirements before entering.','View promotion','/promotion/'+p.id);const win=e.outcome==='win',draw=e.outcome==='draw';return participationShell(p,`<section class="panel result"><span class="result-icon ${!win?'neutral':''}">${icon(win?'gift':draw?'check':'ticket')}</span><span class="eyebrow">${win?'Simulated winning result':draw?'Example entry confirmed':'Simulated result'}</span><h1>${win?'A little JOY, just for you.':draw?'You’re in the draw.':'No prize this time.'}</h1><p>${win?'In this example, you’ve won '+p.prize.toLowerCase()+'.':draw?'Your example entry for '+p.prize.toLowerCase()+' is saved. There’s nothing else you need to do.':'Your entry was received, but it wasn’t a winning entry. You can keep track of this result in My JOY.'}</p>${win&&p.art==='console'?'<img class="result-product" src="assets/console.png" alt="Example console prize">':''}<div class="notice"><strong>${draw?'What happens next':win?'About your example reward':'Your entry is saved'}</strong><p class="small" style="margin-top:8px">${draw?'Example result date: '+date(p.end)+'. A real service would provide the approved notification and claim process.':win?'This prototype cannot issue or redeem prizes. A live win would show a claim deadline, delivery method and support details here.':'No additional survey or information is needed. Explore other promotions whenever you’re ready.'}</p></div><p class="small">Reference ${e.ref} · Entered ${date(e.date)}<br>Simulation only. No real reward or email.</p><div class="row">${button('My activity','/profile')}${button('Explore promotions','/promotions','secondary')}</div><div class="demo-controls"><button class="text-btn" data-replay="${p.id}">Test another outcome</button><p class="small">Replaces this simulated result. No duplicate entry is created.</p></div></section>`,true)}
function join(next=''){return `<section class="auth-scene"><div class="auth-panel"><div class="flow-heading"><span class="eyebrow">Welcome to JOY</span><h1>A little more, from your favourites.</h1><p style="margin-top:16px">Explore the example member experience. This creates no real account.</p></div><form id="join-form" data-next="${esc(next)}" class="panel form-stack" novalidate><div class="notice">Prototype sign-in · No email, password or date of birth is collected.</div><div class="field"><label for="demo-name">Example display name</label><input id="demo-name" maxlength="24" value="Alex" autocomplete="off"></div><div class="field"><label for="join-country">Example market</label><select id="join-country">${opts(['United Kingdom','Ireland','France','Germany','Spain'],state.country)}</select></div><label class="check"><input type="checkbox" id="join-agree"><span>I understand that offers and participation are simulated (required).<small><a href="#/terms">Example terms</a> · <a href="#/privacy">Prototype privacy</a></small></span></label><div class="error" id="join-error" role="alert"></div><button class="btn" type="submit">Continue as example member ${icon('arrow')}</button><a class="text-btn" href="#/promotions">Keep browsing as a guest</a></form></div></section>`}
function profile(){if(!state.signed)return join();let content='';if(profileTab==='Activity')content=`<div class="section-head"><div><h2>Your activity</h2><p class="small">${state.entries.length} example entries · Results and confirmations</p></div></div>${entryRows()}<div class="notice" style="margin-top:24px">Entries are participation records, not points or a redeemable balance. No verified points or coins programme is assumed.</div>`;else if(profileTab==='Rewards')content=`<h2>Your rewards</h2><div style="margin-top:24px">${state.entries.some(e=>e.outcome==='win')?state.entries.filter(e=>e.outcome==='win').map(e=>`<div class="panel stack"><h3>${offers.find(p=>p.id===e.id).prize}</h3><p>Example reward only · No real claim or redemption</p>${button('View example result','/result/'+e.id,'secondary')}</div>`).join(''):empty('No rewards to claim','Try the instant-win example and select “Winning result” to explore the reward screen. Real rewards would appear here after a verified win.','Explore promotions','/promotions')}</div>`;else if(profileTab==='Favourite brands')content=`<h2>Your favourite brands</h2><p style="margin:12px 0 24px">Suggestions use only the brands you follow. No hidden profiling.</p><div class="brand-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${brands.map(brandTile).join('')}</div>`;else if(profileTab==='Preferences')content=`<form id="preferences-form" class="panel prefs"><h2>Only the updates you want.</h2><label class="check"><input id="news-pref" type="checkbox" ${state.notifications?'checked':''}><span>Promotion news from my favourite brands<small>Optional. Saved locally for this demonstration. No email is sent.</small></span></label><div class="notice">Entry status is always available in My JOY. You don’t need marketing notifications to participate.</div><button class="btn" type="submit">Save preferences</button></form>`;else if(profileTab==='Region')content=`<div class="panel prefs"><h2>Region</h2><p>Promotions, dates and eligibility are shown for the country you choose.</p><div class="field"><label for="country">Country</label><select id="country">${opts(markets,state.country)}</select></div><p class="small">Saved on this device for the prototype.</p></div>`;else content=`<form id="personal-form" class="panel prefs"><h2>Personal information & privacy</h2><div class="field"><label for="profile-name">Example display name</label><input id="profile-name" value="${esc(state.name)}" maxlength="24" required></div><p class="small">Your example market is ${state.country}. Change it in Region. No date of birth, address or email is stored.</p><button class="btn" type="submit">Save name</button><a href="#/privacy">How this prototype stores data</a><button type="button" class="btn secondary" data-action="reset-dialog">Reset example data</button></form>`;return `<div class="intro"><span class="eyebrow">Your JOY</span><h1>A home for your good things.</h1><p>Your entries, favourite brands and preferences, together.</p></div><div class="profile-layout"><aside><div class="profile-head"><span class="avatar">${esc(state.name[0])}</span><div><strong>${esc(state.name)}</strong><p class="small">Example member</p></div></div><nav class="side-nav" aria-label="Account sections">${['Activity','Rewards','Favourite brands','Preferences','Region','Personal information'].map(t=>`<button data-profile="${t}" aria-pressed="${profileTab===t}">${t}</button>`).join('')}</nav><button type="button" class="wf-logout" data-action="logout">${icon('back')}Log out</button></aside><div>${content}</div></div>`}
function info(kind){return infoBody(kind).replace(/<\/summary>/g,`${icon('chevronDown')}</summary>`)}
function infoBody(kind){if(kind==='about')return rationale();const privacy=kind==='privacy',terms=kind==='terms';return `<div class="rationale"><span class="eyebrow">${privacy?'Your information':terms?'Before taking part':'A little help'}</span><h1>${privacy?'Prototype privacy':terms?'Example terms':'Good questions. Clear answers.'}</h1><div class="section faq">${privacy?'<p>This browser-only prototype stores your example display name, market, favourite brands, saved promotions, notification setting and simulated entries in local storage on this device. It does not send those values to a backend or marketing service.</p><p>No real sign-in, identity verification, purchases, emails or prize claims are implemented. Private hosting access is separate from the simulated JOY login. Hosting providers may process ordinary access logs.</p><p>Use Reset example data in Personal information to return to the starter example. Do not enter real pack codes or sensitive personal data.</p><a class="btn secondary" href="#/profile">Manage my example data</a>':terms?'<p>All promotions, eligibility, dates, prizes, entry limits and outcomes shown here are illustrative design content. None is an actual offer by PepsiCo or another brand.</p><p>The example date is fixed at 16 October 2026 so Active, Ending soon and Ended states remain predictable for testing. One entry per example promotion is allowed. The supplied test code is JOY2026.</p><p>Official country-specific promotion terms, age limits, purchasing requirements, odds, draw operations and fulfilment would need approval before a real launch. These pages do not provide legal terms for a live promotion.</p>':'<details open><summary>How does participation work?</summary><p>Browse a promotion, check the prize and example requirements, and select Take part. Draws confirm your entry. Instant wins show a result immediately.</p></details><details><summary>What is the difference between a draw and an instant win?</summary><p>A draw confirms participation and tells you when to expect a result. An instant win returns a result immediately. Neither guarantees a prize.</p></details><details><summary>Do entries earn points or coins?</summary><p>No points conversion is assumed. Entries, results and illustrative rewards are tracked separately.</p></details><details><summary>Why are some promotions missing?</summary><p>The gallery shows available examples for your selected market. Ended offers have their own filter. Brand pages show only that brand’s offers.</p></details><details><summary>Can I claim a prize?</summary><p>No. This is a design prototype with simulated entries and outcomes.</p></details>'}</div></div>`}
function rationale(){return `<article class="rationale"><span class="eyebrow">Research · structure · experience</span><h1>More clarity. More JOY.</h1><p style="margin-top:24px">A responsive, interactive redesign built from the supplied research, wireframes and JOY design system. This prototype is ready for usability testing; it has not been validated with participants.</p><h2>What informed the design</h2><p>The 39-page PepsiCo × Purdue UX report records six interviews with people aged 18–24 from the US and UK and three cognitive walkthroughs with UX students aged 18–24. These are directional findings, not a representative EU market study. FigJam includes raw notes, synthesis and proposed concepts.</p><table><thead><tr><th>Research finding</th><th>Design decision</th><th>Screen affected</th></tr></thead><tbody>${[
['Prizes motivated participation; requirements often came first (PDF pp. 14–16).','Put the prize, eligibility, deadline and entry requirement before the primary action.','Cards and details'],
['Active and expired promotions looked alike (pp. 14, 16).','Default to available offers; separate ended offers, label their status and disable entry.','Gallery and brand pages'],
['Participants struggled to find relevant brand promotions (p. 16).','Search, brand/type filters and country-specific examples; brand pages contain only their own offers.','Discovery'],
['A second sign-in and additional agreements fragmented participation (pp. 16, 26).','One session and one entry form; retain the intended promotion after example login.','Onboarding and entry'],
['Post-loss surveys felt intrusive; instant outcomes were unclear (pp. 14, 16).','Explain the result type in advance and show neutral no-prize copy with useful next actions.','Details and results'],
['Interviews favoured understandable value and ongoing benefits (pp. 17–19).','State the tangible prize, show follow-up activity and personalise by explicitly followed brands.','Home and profile'],
['Point value and expiry were unclear; reward thresholds felt high (pp. 18–19).','Do not invent a shared currency or conversion. Keep entries and rewards distinct.','Home and profile'],
['Navigation did not show the current location (p. 14).','Active navigation, explicit breadcrumbs and return links.','All screens']
].map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('')}</tbody></table><h2>What was retained and refined</h2><p>Retained: Home / Promotions / Brands navigation; guest and member homes; Suggested and Entered promotions; prize-first detail sections; steps, FAQs and terms; central result panels. Rebuilt from the designer’s wireframes (21 Oct 2026): guest home leads with Register to participate, then How to play (Snack · Play · Win) and suggested promotions; member home greets by name with an entry milestone meter, then Suggested and Entered promotions; the gallery has a manually controlled featured carousel (no autoplay), search, a Filters panel and a card grid where expired offers sit last and are clearly tabbed; details pages follow Prizes · Steps · FAQs · Terms with a sticky Participate now action. The milestone meter is labelled as an example: the research found point values and thresholds unclear (pp. 18–19), so its rule is stated beside it and needs validation before launch.</p><h2>The JOY visual system, in code</h2><p>Uses JOY #1443FF and the exact semantic themes for Doritos and Rockstar, nine supplied type styles, Galano typography from the live JOY website, the spacing scale, 20px card corners, 44px pill controls, 24px card padding and 12px × 20px button padding. The live JOY GB site supplies the full-width campaign composition, lifestyle and product artwork, official brand logos, blue header and footer, white logo, yellow #FFE600 hero buttons, Galano font and decorative shapes. Fields and status badges retain the Figma variants. The promotion card extends the supplied card foundation with the discovery information the research calls for. The supplied current-interface screenshots extend the shared system with Pepsi black, 7UP green, curved banners, circular artwork, wide promotion cards, a brand menu and split participation layouts. Doritos and Rockstar keep their supplied brand themes. Registration stays visually familiar while avoiding unnecessary personal fields.</p><h2>Explore the connected journeys</h2><p>Switch guest/member examples in the footer. Search and filter promotions. Follow brands. Open a promotion and submit JOY2026. Choose a no-prize, winning or connection-error scenario for instant win; view the saved result in My JOY. Reset example data to repeat a completed flow.</p><h2>Scope and next validation</h2><p>All offers, rules and dates are illustrative. Ticket artwork is a prize illustration; the console comes from the supplied wireframes; the white JOY logo, font and decoration come from the live JOY site. No artificial points, real authentication, CRM, email, draw service or redemption is implemented.</p><p>Next: test reward comprehension, finding an eligible promotion, distinguishing instant win from a draw, recovering from invalid input and locating a result. Include participants in target EU markets and assistive-technology users. Confirm market rules and content with the programme team before a live implementation.</p><div class="row"><a href="https://www.joy-pepsico.eu/en-gb/" target="_blank" rel="noopener">Live JOY visual reference${ext}</a><a href="https://www.figma.com/design/AJ0GKjFjDNvEsD4MfdyZaN/AI-Assisted-Design-System?node-id=14-2" target="_blank" rel="noopener">Design system${ext}</a><a href="https://www.figma.com/board/C0aRujYsmrf64Mk2EeYSJm/Figjam-Documentation?node-id=0-1" target="_blank" rel="noopener">Research board${ext}</a><a href="https://www.figma.com/design/IMEy8gioQJFpGIgb9qIUJe/Wireframes?node-id=0-1" target="_blank" rel="noopener">Wireframes${ext}</a></div></article>`}
function breadcrumbBar(){const r=route();if(r==='/')return '';const part=r.split('/')[1].split('?')[0],p=offers.find(x=>x.id===r.split('/')[2]);let crumbs='<a href="#/">Home</a>';if(['promotion','enter','result','reveal'].includes(part)&&p){crumbs+=`<a href="#/brands">Brands</a>${brands.includes(p.brand)?`<a href="#/brand/${p.brand}">${p.brand}</a>`:`<span>${p.brand}</span>`}<a href="#/promotions">Promotions</a>`;crumbs+=part==='promotion'?`<span aria-current="page">${p.prize}</span>`:`<a href="#/promotion/${p.id}">${p.prize}</a><span aria-current="page">${part==='enter'?'Participation':'Result'}</span>`;}else if(part==='brand')crumbs+=`<a href="#/brands">Brands</a><span>${esc(decodeURIComponent(r.split('/')[2]))}</span>`;else crumbs+=`<span>${({promotions:'Promotions',brands:'Brands',join:'Join JOY',profile:'My JOY',about:'Design rationale',help:'Help',terms:'Example terms',privacy:'Privacy'})[part]||'JOY'}</span>`;return `<nav class="breadcrumb-bar" aria-label="Breadcrumb">${crumbs}</nav>`}
function render(){const r=route();let content;document.body.removeAttribute('data-theme');if(r==='/')content=home();else if(r==='/promotions')content=gallery();else if(r==='/brands')content=brandsPage();else if(r.startsWith('/brand/')){const b=decodeURIComponent(r.split('/')[2]);content=brands.includes(b)?brandPage(b):empty('Brand not found','Browse the available example brands.','All brands','/brands')}else if(r.startsWith('/promotion/')||r.startsWith('/enter/')||r.startsWith('/result/')||r.startsWith('/reveal/')){const p=offers.find(p=>p.id===r.split('/')[2]);content=p?(r.startsWith('/enter/')?enter(p):r.startsWith('/result/')?result(p):r.startsWith('/reveal/')?reveal(p):details(p)):empty('Promotion not found','This link does not match an example promotion.','Browse promotions','/promotions')}else if(r.startsWith('/join'))content=join(r.split('next=')[1]||'');else if(r.startsWith('/profile')){if(r.endsWith('/preferences'))profileTab='Preferences';content=profile()}else if(['/about','/privacy','/terms','/help'].includes(r))content=info(r.slice(1));else content=empty('Let’s get you back to JOY.','That page isn’t part of this prototype.','Go home','/');content=content.replace(/<nav class="breadcrumbs"[\s\S]*?<\/nav>/g,'');$('#app').innerHTML=header()+breadcrumbBar()+`<main class="main ${r==='/'||r==='/promotions'||r.startsWith('/promotion/')||r.startsWith('/brand/')?'home-main':r.startsWith('/enter/')||r.startsWith('/result/')||r.startsWith('/reveal/')||r.startsWith('/join')||(r.startsWith('/profile')&&!state.signed)?'full-main':'container'} ${r.startsWith('/promotion/')?'promotion-page':''}" id="main" tabindex="-1">${content}</main>`+footer();updateResults();sizeHero();startReveal();document.title=($('.main h1')?.textContent||'Explore rewards')+' | JOY';}
function openDialog(title,body){returnFocus=document.activeElement;$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;$('#dialog').showModal()}
document.addEventListener('click',e=>{if(suppressClick&&e.target.closest('.wf-viewport')){e.preventDefault();return}const b=e.target.closest('button,a');if(!b)return;if(b.classList.contains('skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}if(b.dataset.replay){entryDraft={replay:b.dataset.replay};go('/enter/'+b.dataset.replay);return}if(b.dataset.scroll){e.preventDefault();$('#'+b.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return}if(b.dataset.favourite){const v=b.dataset.favourite;state.favourites=state.favourites.includes(v)?state.favourites.filter(x=>x!==v):[...state.favourites,v];persist();render();document.querySelector(`[data-favourite="${v}"]`)?.focus({preventScroll:true});toast(state.favourites.includes(v)?`${v} followed. Suggestions updated.`:`${v} unfollowed.`);return}if(b.dataset.save){const v=b.dataset.save;state.saved=state.saved.includes(v)?state.saved.filter(x=>x!==v):[...state.saved,v];persist();const saved=state.saved.includes(v);b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',`${saved?'Unsave':'Save'} ${offers.find(p=>p.id===v).prize}`);if(route()==='/promotions'&&filters.status==='Saved')updateResults();toast(saved?'Promotion saved. Find it in Saved.':'Promotion removed from Saved.');return}if(b.dataset.slide){setSlide(Number(b.dataset.slide));return}if(b.dataset.other){const t=$('#others-track');t.scrollTo({left:Number(b.dataset.other)*t.clientWidth,behavior:reducedMotion()?'instant':'smooth'});return}if(b.dataset.action==='others-prev'||b.dataset.action==='others-next'){const t=$('#others-track'),n=t.children.length,i=Math.round(t.scrollLeft/t.clientWidth),j=(i+(b.dataset.action==='others-next'?1:-1)+n)%n;t.scrollTo({left:j*t.clientWidth,behavior:reducedMotion()?'instant':'smooth'});return}if(b.dataset.status){filters.status=b.dataset.status;render();document.querySelector(`[data-status="${filters.status}"]`)?.focus({preventScroll:true});return}if(b.dataset.profile){profileTab=b.dataset.profile;if(route()!=='/profile'){location.hash='/profile'}else render();return}switch(b.dataset.action){case'menu':menuOpen=!menuOpen;$('.header').classList.toggle('menu-open',menuOpen);b.setAttribute('aria-expanded',String(menuOpen));b.innerHTML=icon(menuOpen?'close':'menu');break;case'toggle-auth':state.signed=!state.signed;persist();go('/');toast(state.signed?'Logged-in example enabled.':'Logged-out example enabled.');break;case'clear-filters':filters={q:'',brand:'All brands',type:'All types',status:'All',sort:'recommended'};render();$('#brand-filter')?.focus();break;case'logout':state.signed=false;profileTab='Activity';persist();go('/');toast('You’ve logged out of the example account.');break;case'prize-prev':case'prize-next':$('#prize-track').scrollBy({left:(b.dataset.action==='prize-next'?1:-1)*$('#prize-track').clientWidth,behavior:'smooth'});break;case'change-country':if(state.signed){profileTab='Region';go('/profile');setTimeout(()=>$('#country')?.focus(),50)}else openDialog('Choose your region',`<div class="field"><label for="country">Country</label><select id="country">${opts(markets,state.country)}</select></div><div class="row" style="margin-top:20px"><button class="btn" data-action="close-dialog">Done</button></div>`);break;case'save-draft':entryDraft={...entryDraft,code:$('#entry-code')?.value,eligible:$('#eligible')?.checked,rules:$('#rules-agree')?.checked};break;case'reset-dialog':openDialog('Reset this example?',`<p>This clears your changes and restores the starter guest view, favourites and two illustrative entries on this browser.</p><div class="row"><button class="btn" data-action="reset">Reset example data</button><button class="btn secondary" data-action="close-dialog">Keep my changes</button></div>`);break;case'reset':state=structuredClone(seed);persist();entryDraft={};$('#dialog').close();render();toast('Starter example restored.');break;case'close-dialog':$('#dialog').close();break}});
$('#dialog').addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus()});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.q=e.target.value;updateResults()}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='country'){state.country=el.value;persist();render();toast('Example market changed to '+state.country)}else if(el.id==='brand-filter'){filters.brand=el.value;updateResults()}else if(el.id==='type-filter'){filters.type=el.value;updateResults()}else if(el.id==='availability'){filters.status=el.value;document.querySelectorAll('[data-status]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.status===filters.status)));updateResults()}else if(el.id==='sort'){filters.sort=el.value;updateResults()}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='entry-form'){const p=offers.find(p=>p.id===f.dataset.id),code=$('#entry-code'),error=$('#form-error');error.textContent='';if(code){const valid=code.value.replace(/\s/g,'').toUpperCase()==='JOY2026';code.setAttribute('aria-invalid',String(!valid));$('#code-error').textContent=valid?'':'Use JOY2026 for this example. No real pack code is needed.';if(!valid){code.focus();return}}if(!$('#eligible').checked||!$('#rules-agree').checked){error.textContent='Please confirm both required statements before continuing.';(!$('#eligible').checked?$('#eligible'):$('#rules-agree')).focus();return}const outcome=$('#test-outcome').value,submit=f.querySelector('button[type=submit]');submit.disabled=true;submit.innerHTML='<span>Submitting example…</span>';f.setAttribute('aria-busy','true');await new Promise(resolve=>setTimeout(resolve,500));if(!f.isConnected)return;if(outcome==='error'){submit.disabled=false;submit.innerHTML='Try again '+icon('arrow');f.removeAttribute('aria-busy');error.textContent='The example connection failed. Your entry was not submitted. Your information is still here. Choose a result scenario and try again.';$('#test-outcome').value=p.type==='Instant win'?'loss':'draw';error.tabIndex=-1;error.focus();return}const existing=entry(p); if(existing&&entryDraft.replay===p.id){existing.outcome=outcome;existing.date='2026-10-16'}else if(!existing)state.entries.unshift({id:p.id,outcome,date:'2026-10-16',ref:'JOY-DEMO-'+(1003+state.entries.length)});persist();entryDraft={};go((p.type==='Instant win'?'/reveal/':'/result/')+p.id)}else if(f.id==='join-form'){if(!$('#join-agree').checked){$('#join-error').textContent='Please acknowledge the simulation before continuing.';$('#join-agree').focus();return}state.name=$('#demo-name').value.trim()||'Alex';state.country=$('#join-country').value;state.signed=true;persist();go(f.dataset.next?'/promotion/'+f.dataset.next:'/');toast('Welcome to the example member experience.')}else if(f.id==='newsletter-form'){const em=$('#news-email'),ok=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em.value.trim());em.setAttribute('aria-invalid',String(!ok));em.closest('.ds-field').classList.toggle('is-error',!ok);$('#news-error').textContent=ok?'We only use this to send promotion news.':'Enter an email address like name@example.com.';if(!ok){em.focus();return}em.value='';toast('Subscribed in this example. No email was stored or sent.')}else if(f.id==='preferences-form'){state.notifications=$('#news-pref').checked;persist();toast('Example preferences saved. No email will be sent.')}else if(f.id==='personal-form'){state.name=$('#profile-name').value.trim()||'Alex';persist();render();toast('Example display name saved.')}});
let drag=null,suppressClick=false;document.addEventListener('pointerdown',e=>{const v=e.target.closest('.wf-viewport');if(!v||e.button>0)return;drag={x:e.clientX,y:e.clientY,dx:0,w:v.clientWidth,id:e.pointerId,moved:false};$('.wf-track').style.transition='none'});document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;drag.dx=e.clientX-drag.x;if(!drag.moved&&Math.abs(drag.dx)>6&&Math.abs(drag.dx)>Math.abs(e.clientY-drag.y)){drag.moved=true;$('.wf-viewport').classList.add('dragging')}if(drag.moved)$('.wf-track').style.transform=`translateX(calc(-${(slide+1)*100}% + ${drag.dx}px))`});const endDrag=e=>{if(!drag||e.pointerId!==drag.id)return;const d=drag;drag=null;if(!$('.wf-track'))return;$('.wf-viewport').classList.remove('dragging');if(!d.moved){trackTo(slide+1,false);return}suppressClick=true;setTimeout(()=>suppressClick=false,0);setSlide(slide+(Math.abs(d.dx)>d.w*.15?(d.dx<0?1:-1):0))};document.addEventListener('pointerup',endDrag);document.addEventListener('pointercancel',endDrag);window.addEventListener('resize',sizeHero);document.addEventListener('scroll',e=>{if(e.target.id!=='others-track')return;const t=e.target,i=Math.round(t.scrollLeft/t.clientWidth);document.querySelectorAll('[data-other]').forEach((d,k)=>d.setAttribute('aria-current',String(k===i)))},true);
window.addEventListener('hashchange',()=>{menuOpen=false;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});
render();

